import{_ as a,c as e,o as t,a4 as o}from"./chunks/framework.CpVK_f0P.js";const m=JSON.parse('{"title":"学习心得","description":"","frontmatter":{},"headers":[],"relativePath":"method/lessons-learned.md","filePath":"method/lessons-learned.md"}'),r={name:"method/lessons-learned.md"},n=o('<h1 id="学习心得" tabindex="-1">学习心得 <a class="header-anchor" href="#学习心得" aria-label="Permalink to &quot;学习心得&quot;">​</a></h1><p>记录从实际学习中总结出的心得。只保留当前仍然适用的内容。</p><h2 id="输入和输出的关系" tabindex="-1">输入和输出的关系 <a class="header-anchor" href="#输入和输出的关系" aria-label="Permalink to &quot;输入和输出的关系&quot;">​</a></h2><p>在前期（2024.4 - 2024.12）投入了大量时间做听力输入，累积了 700 多个小时后才开始输出。现在回看，输入的基础是必要的，但应该更早开始少量输出练习。输入和输出不是先后关系，而是可以并行的。</p><h2 id="背单词的局限" tabindex="-1">背单词的局限 <a class="header-anchor" href="#背单词的局限" aria-label="Permalink to &quot;背单词的局限&quot;">​</a></h2><p>持续背了一年单词（17 年开始断断续续，24 年系统性背诵），词汇量一直在 7000 左右。单纯背单词对口语帮助有限，词汇需要在句子和场景中使用才能真正掌握。25 年 2 月已停止专门背单词，改为在听力和工作材料中收集新词，放进完整句子里记忆。</p><h2 id="控制学习强度" tabindex="-1">控制学习强度 <a class="header-anchor" href="#控制学习强度" aria-label="Permalink to &quot;控制学习强度&quot;">​</a></h2><p>之前每天 3-4 小时，持续一年后暂停。现在调整为每天 60-90 分钟，降低强度换取可持续性。每天能坚持 30 分钟的有效训练，比偶尔突击 3 小时有用。</p><h2 id="不要追求完整体系" tabindex="-1">不要追求完整体系 <a class="header-anchor" href="#不要追求完整体系" aria-label="Permalink to &quot;不要追求完整体系&quot;">​</a></h2><p>之前系统整理了 16 种时态、大量语法规则、句型分类等。这些资料看起来完整，但实际上很少回头翻阅。语法和句型应该在犯错时针对性学习，不需要提前建立完整体系。</p><h2 id="口语和书面语是不同的" tabindex="-1">口语和书面语是不同的 <a class="header-anchor" href="#口语和书面语是不同的" aria-label="Permalink to &quot;口语和书面语是不同的&quot;">​</a></h2><p>能读懂英文技术文章不代表能说出来。口语需要单独训练，而且核心是&quot;能想起来&quot;，不是&quot;看得懂&quot;。</p><h2 id="语音转写不等于真实水平" tabindex="-1">语音转写不等于真实水平 <a class="header-anchor" href="#语音转写不等于真实水平" aria-label="Permalink to &quot;语音转写不等于真实水平&quot;">​</a></h2><p>用语音输入练习复述时，转写结果里的错误不全是语法错误，有些是识别错误。记录训练时需要区分。</p><h2 id="简单句优先" tabindex="-1">简单句优先 <a class="header-anchor" href="#简单句优先" aria-label="Permalink to &quot;简单句优先&quot;">​</a></h2><p>卡住的时候不要硬想复杂句。主动降级为简单句，先把意思说出来，比沉默好。</p>',16),h=[n];function s(l,i,d,c,p,_){return t(),e("div",null,h)}const q=a(r,[["render",s]]);export{m as __pageData,q as default};
